	"domain_needs_a_domain_name = --domain needs a domain name\n"
	"unknown_option = unknown option\n"
	"try_help = try: matlog help\n"
	"\n"
	"# Labels of the screen. {title} is the title of the help page.\n"
	"[ui]\n"
	"help_bar = -- HELP -- {title}  (Tab links, Enter follow, Backspace bac"
	"k, / search, q close)\n"
	"\n"
	"# Pages made while the program runs. {table} is the table of keys.\n"
	"[pages]\n"
	"yourkeys = <<\n"
	"id: yourkeys\n"
	"title: Your keys\n"
	"summary: The key bindings in use.\n"
	"see: keys\n"
	"\n"
	"The action, its keys and what it does. `:map KEY ACTION` binds a key,\n"
	"`:unmap KEY` removes one; both are kept in the settings file.\n"
	"\n"
	"```keys\n"
	"{table}```\n"
	">>\n"
	"\n"
	"# The lessons of the tutorial are in the files lessons/en/*.mltext, on"
	"e lesson per\n"
	"# file, built into the program in the same way and read in the order o"
	"f their names.\n";

static const char text_lessons_en_01_notes [] =
	"# The lessons of the tutorial. A lesson is an id with a title and a st"
	"age (1: the\n"
	"# tool, 2: the syntax); its steps are numbered from 1. A step has `che"
	"ck` (what\n"
	"# the editor must show for the step to be done: action, key, notes, re"
	"sult,\n"
	"# error, value, domain, state, state_not, command, steps or watch), `a"
	"rg` for\n"
	"# some of the checks (the action, the key, the domain, the state, on o"
	"r off, a\n"
	"# number), `param` and `param2` for the checks that compare text, the "
	"`text`\n"
	"# the user reads, a `hint` shown after a few keys that did not do it, "
	"and the\n"
	"# `answer`: the keys of a model answer, a key between < > is pressed. "
	"A new\n"
	"# lesson is new entries with a new id. The tests play every answer.\n"
	"\n"
	"# Lesson 1: Writing and notes\n"
	"[lessons]\n"
	"notes.title = Writing and notes\n"
	"notes.stage = 1\n"
	"\n"
	"notes.1.check = notes\n"
	"notes.1.arg = 1\n"
	"notes.1.text = Welcome. A new line is a note, free text. Type a senten"
	"ce and\n"
	"    press Enter.\n"
	"notes.1.hint = Type some letters, then press the Enter key.\n"
	"notes.1.answer = My first note<Enter>\n"
	"\n"
	"notes.2.check = key\n"
	"notes.2.arg = Up\n"
	"notes.2.text = Press Up to go back to your note. The cursor moves acro"
	"ss\n"
	"    lines like in any text editor.\n"
	"notes.2.hint = The key with the arrow pointing up.\n"
	"notes.2.answer = <Up>\n"
	"\n"
	"notes.3.check = key\n"
	"notes.3.arg = Enter\n"
	"notes.3.text = Press End to jump to the end of the line, then Enter: a"
	" new\n"
	"    line starts below it.\n"
	"notes.3.hint = End is next to Home. Then the Enter key.\n"
	"notes.3.answer = <End><Enter>\n";

static const char text_lessons_en_02_math [] =
	"# Lesson 2: Math lines\n"
	"[lessons]\n"
	"math.title = Math lines\n"
	"math.stage = 1\n"
	"\n"
	"math.1.check = action\n"
	"math.1.arg = block-new\n"
	"math.1.text = Press {ACTION_BLOCK_NEW}. A math line starts, in a block"
	" of\n"
	"    the domain used last (algebra at first).\n"
	"math.1.hint = Hold Ctrl and press Enter. Some terminals send Shift and"
	" Enter\n"
	"    together for it.\n"
	"math.1.answer = <ACTION_BLOCK_NEW>\n"
	"\n"
	"math.2.check = result\n"
	"math.2.param = 1/2\n"
	"math.2.text = Type 1/3 + 1/6. The dim text after it is a preview of th"
	"e\n"
	"    result. Press Enter to keep the line.\n"
	"math.2.hint = Type the characters 1/3 + 1/6 exactly, then Enter.\n"
	"math.2.answer = 1/3 + 1/6<Enter>\n"
	"\n"
	"math.3.check = result\n"
	"math.3.param = 12\n"
	"math.3.text = Lines work in order: a name you define is known below it"
	". Type\n"
	"    a = 12 and press Enter.\n"
	"math.3.hint = Type a = 12 and press Enter.\n"
	"math.3.answer = a = 12<Enter>\n"
	"\n"
	"math.4.check = result\n"
	"math.4.param = 5/2\n"
	"math.4.text = Use it: type a/8 + 1 and press Enter.\n"
	"math.4.hint = a/8 + 1 with a being 12 gives 5/2.\n"
	"math.4.answer = a/8 + 1<Enter>\n"
	"\n"
	"math.5.check = error\n"
	"math.5.param = div_zero\n"
	"math.5.text = A line that cannot be computed shows a message in red. T"
	"ype\n"
	"    1/0 and press Enter.\n"
	"math.5.hint = One divided by zero.\n"
	"math.5.answer = 1/0<Enter>\n"
	"\n"
	"math.6.check = state\n"
	"math.6.arg = note\n"
	"math.6.text = Enter on an empty line of a block ends the block, and a "
	"note\n"
	"    starts below it. Press Enter.\n"
	"math.6.hint = The line you are on is empty. Press Enter on it.\n"
	"math.6.answer = <Enter>\n";

static const char text_lessons_en_03_moving [] =
	"# Lesson 3: Moving around\n"
	"[lessons]\n"
	"moving.title = Moving around\n"
	"moving.stage = 1\n"
	"\n"
	"moving.1.check = action\n"
	"moving.1.arg = goto-first\n"
	"moving.1.text = {ACTION_GOTO_FIRST} goes to the first line of the sess"
	"ion.\n"
	"moving.1.answer = <ACTION_GOTO_FIRST>\n"
	"\n"
	"moving.2.check = action\n"
	"moving.2.arg = goto-last\n"
	"moving.2.text = {ACTION_GOTO_LAST} goes to the last line.\n"
	"moving.2.answer = <ACTION_GOTO_LAST>\n"
	"\n"
	"moving.3.check = action\n"
	"moving.3.arg = block-prev\n"
	"moving.3.text = {ACTION_BLOCK_PREV} jumps to the block before,\n"
	"    {ACTION_BLOCK_NEXT} to the next one. Press {ACTION_BLOCK_PREV}.\n"
	"moving.3.answer = <ACTION_BLOCK_PREV>\n"
	"\n"
	"moving.4.check = action\n"
	"moving.4.arg = block-next\n"
	"moving.4.text = {ACTION_BLOCK_NEXT} jumps to the next block.\n"
	"moving.4.answer = <ACTION_BLOCK_NEXT>\n";

static const char text_lessons_en_04_editing [] =
	"# Lesson 4: Selecting, copying, undo\n"
	"[lessons]\n"
	"editing.title = Selecting, copying, undo\n"
	"editing.stage = 1\n"
	"\n"
	"editing.1.check = action\n"
	"editing.1.arg = select-line\n"
	"editing.1.text = Go up one line and press {ACTION_SELECT_LINE} to sele"
	"ct the\n"
	"    whole line.\n"
	"editing.1.hint = Press Up, then hold Ctrl and press L.\n"
	"editing.1.answer = <Up><ACTION_SELECT_LINE>\n"
	"\n"
	"editing.2.check = action\n"
	"editing.2.arg = copy\n"
	"editing.2.text = {ACTION_COPY} copies the selected lines.\n"
	"editing.2.answer = <ACTION_COPY>\n"
	"\n"
	"editing.3.check = action\n"
	"editing.3.arg = paste\n"
	"editing.3.text = Press Down to leave the selection, then {ACTION_PASTE"
	"} to\n"
	"    paste the copy below.\n"
	"editing.3.answer = <Down><ACTION_PASTE>\n"
	"\n"
	"editing.4.check = action\n"
	"editing.4.arg = undo\n"
	"editing.4.text = {ACTION_UNDO} undoes the last change. Try it.\n"
	"editing.4.answer = <ACTION_UNDO>\n"
	"\n"
	"editing.5.check = action\n"
	"editing.5.arg = redo\n"
	"editing.5.text = {ACTION_REDO} redoes what was undone.\n"
	"editing.5.answer = <ACTION_REDO>\n";

static const char text_lessons_en_05_domains [] =
	"# Lesson 5: Domains and commands\n"
	"[lessons]\n"
	"domains.title = Domains and commands\n"
	"domains.stage = 1\n"
	"\n"
	"domains.1.check = action\n"
	"domains.1.arg = domain-next\n"
	"domains.1.text = Every math line has a domain: algebra, lambda, pga2, "
	"pga3\n"
	"    or boolean. The label at the left shows it. {ACTION_DOMAIN_NEXT} g"
	"oes to\n"
	"    the next domain.\n"
	"domains.1.hint = Hold Alt and press the right arrow.\n"
	"domains.1.answer = <ACTION_DOMAIN_NEXT>\n"
	"\n"
	"domains.2.check = action\n"
	"domains.2.arg = block-pick\n"
	"domains.2.text = {ACTION_BLOCK_PICK} chooses the domain of a new block\n"
	"    first. Press it.\n"
	"domains.2.answer = <ACTION_BLOCK_PICK>\n"
	"\n"
	"domains.3.check = key\n"
	"domains.3.arg = Esc\n"
	"domains.3.text = Press Esc to cancel the choice.\n"
	"domains.3.answer = <Esc>\n"
	"\n"
	"domains.4.check = command\n"
	"domains.4.param = mode boolean\n"
	"domains.4.text = {ACTION_COMMAND} opens the command line. Type mode bo"
	"olean\n"
	"    and press Enter: new blocks are boolean from now on.\n"
	"domains.4.hint = {ACTION_COMMAND}, then the words mode boolean, then E"
	"nter.\n"
	"domains.4.answer = <ACTION_COMMAND>mode boolean<Enter>\n"
	"\n"
	"domains.5.check = result\n"
	"domains.5.param = false\n"
	"domains.5.text = Start a block with {ACTION_BLOCK_NEW}, type a & ~a an"
	"d\n"
	"    press Enter. In the boolean domain & is and, ~ is not.\n"
	"domains.5.hint = a and not a is never true.\n"
	"domains.5.answer = <ACTION_BLOCK_NEW>a & ~a<Enter>\n"
	"\n"
	"domains.6.check = command\n"
	"domains.6.param = mode algebra\n"
	"domains.6.text = Back to algebra: {ACTION_COMMAND}, then mode algebra "
	"and\n"
	"    Enter.\n"
	"domains.6.answer = <ACTION_COMMAND>mode algebra<Enter>\n";

static const char text_lessons_en_06_steps [] =
	"# Lesson 6: Results and steps\n"
	"[lessons]\n"
	"steps.title = Results and steps\n"
	"steps.stage = 1\n"
	"\n"
	"steps.1.check = result\n"
	"steps.1.param = -2\n"
	"steps.1.text = Start a block and write det([[1,2],[3,4]]), the determi"
	"nant\n"
	"    of a matrix. Press Enter.\n"
	"steps.1.hint = {ACTION_BLOCK_NEW}, then the text, then Enter.\n"
	"steps.1.answer = <ACTION_BLOCK_NEW>det([[1,2],[3,4]])<Enter>\n"
	"\n"
	"steps.2.check = steps\n"
	"steps.2.text = Go up to that line and press {ACTION_STEPS}: the steps "
	"of the\n"
	"    calculation are shown under it.\n"
	"steps.2.hint = Press Up once, then {ACTION_STEPS}.\n"
	"steps.2.answer = <Up><ACTION_STEPS>\n"
	"\n"
	"steps.3.check = action\n"
	"steps.3.arg = steps\n"
	"steps.3.text = {ACTION_STEPS} again hides the steps.\n"
	"steps.3.answer = <ACTION_STEPS>\n";

static const char text_lessons_en_07_help [] =
	"# Lesson 7: Help and the watch window\n"
	"[lessons]\n"
	"help.title = Help and the watch window\n"
	"help.stage = 1\n"
	"\n"
	"help.1.check = state\n"
	"help.1.arg = help\n"
	"help.1.text = {ACTION_HELP} opens the help. Every page of the document"
	"ation\n"
	"    is there, and it can be searched.\n"
	"help.1.answer = <ACTION_HELP>\n"
	"\n"
	"help.2.check = state_not\n"
	"help.2.arg = help\n"
	"help.2.text = Press q to close the help.\n"
	"help.2.answer = q\n"
	"\n"
	"help.3.check = watch\n"
	"help.3.arg = on\n"
	"help.3.text = {ACTION_WATCH} shows the watch window: every name define"
	"d at\n"
	"    the line of the cursor, with its type and value.\n"
	"help.3.answer = <ACTION_WATCH>\n"
	"\n"
	"help.4.check = watch\n"
	"help.4.arg = off\n"
	"help.4.text = {ACTION_WATCH} hides it again.\n"
	"help.4.answer = <ACTION_WATCH>\n";

static const char text_lessons_en_08_numbers [] =
	"# Lesson 8: Numbers and operators\n"
	"[lessons]\n"
	"numbers.title = Numbers and operators\n"
	"numbers.stage = 2\n"
	"\n"
	"numbers.1.check = result\n"
	"numbers.1.param = 1/2\n"
	"numbers.1.text = Start a block ({ACTION_BLOCK_NEW}) and write a line w"
	"hose\n"
	"    result is 1/2. Any way will do, 2/4 or 1/3 + 1/6.\n"
	"numbers.1.hint = Fractions are exact: 2/4 is 1/2.\n"
	"numbers.1.answer = <ACTION_BLOCK_NEW>2/4<Enter>\n"
	"\n"
	"numbers.2.check = result\n"
	"numbers.2.param = -4\n"
	"numbers.2.text = ^ is the power and -2^2 is -4, not 4. Write a line wh"
	"ose\n"
	"    result is -4.\n"
	"numbers.2.answer = -2^2<Enter>\n"
	"\n"
	"numbers.3.check = result\n"
	"numbers.3.param = 120\n"
	"numbers.3.text = Write a line whose result is 120 with a factorial: 5!\n"
	"numbers.3.answer = 5!<Enter>\n"
	"\n"
	"numbers.4.check = result\n"
	"numbers.4.param = \342\211\210 1.41421356\n"
	"numbers.4.text = A root that is not a fraction is an approximation, ma"
	"rked\n"
	"    with \342\211\210. Write sqrt(2).\n"
	"numbers.4.answer = sqrt(2)<Enter>\n";

static const char text_lessons_en_09_names [] =
	"# Lesson 9: Names and functions\n"
	"[lessons]\n"
	"names.title = Names and functions\n"
	"names.stage = 2\n"
	"\n"
	"names.1.check = value\n"
	"names.1.param = g(2)\n"
	"names.1.param2 = 7\n"
	"names.1.text = Define a function g so that g(2) is 7. A function is wr"
	"itten\n"
	"    g(x) = ...\n"
	"names.1.hint = For example g(x) = 3x + 1.\n"
	"names.1.answer = g(x) = 3x + 1<Enter>\n"
	"\n"
	"names.2.check = result\n"
	"names.2.param = 12\n"
	"names.2.text = A name is a whole word: 2x is 2 times x, but xy is one "
	"name.\n"
	"    Define x = 4, then write 3x on the next line.\n"
	"names.2.answer = x = 4<Enter>3x<Enter>\n"
	"\n"
	"names.3.check = result\n"
	"names.3.param = \342\211\210 3.14159265\n"
	"names.3.text = pi and e are constants. Write a line whose result is th"
	"e\n"
	"    approximation of pi.\n"
	"names.3.answer = pi<Enter>\n";

static const char text_lessons_en_10_errors [] =
	"# Lesson 10: Reading errors\n"
	"[lessons]\n"
	"errors.title = Reading errors\n"
	"errors.stage = 2\n"
	"\n"
	"errors.1.check = error\n"
	"errors.1.param = \n"
	"errors.1.text = Write a line with a mistake, 2 +, and press Enter. The\n"
	"    message says what is wrong and the place is marked.\n"
	"errors.1.answer = 2 +<Enter>\n"
	"\n"
	"errors.2.check = result\n"
	"errors.2.param = 4\n"
	"errors.2.text = Write the line right: a line whose result is 4.\n"
	"errors.2.answer = 2 + 2<Enter>\n";

static const char text_lessons_en_11_matrices [] =
	"# Lesson 11: Matrices\n"
	"[lessons]\n"
	"matrices.title = Matrices\n"
	"matrices.stage = 2\n"
	"\n"
	"matrices.1.check = result\n"
	"matrices.1.param = -2\n"
	"matrices.1.text = A matrix is a list of rows: [[1,2],[3,4]]. Write a l"
	"ine\n"
	"    with its determinant, det([[1,2],[3,4]]), which is -2.\n"
	"matrices.1.answer = det([[1,2],[3,4]])<Enter>\n"
	"\n"
	"matrices.2.check = result\n"
	"matrices.2.param = [[4/5], [7/5]]\n"
	"matrices.2.text = Solve the system 2x + y = 3 and x + 3y = 5 with\n"
	"    solve([[2,1],[1,3]], [3,5]).\n"
	"matrices.2.answer = solve([[2,1],[1,3]], [3,5])<Enter>\n";

static const char text_lessons_en_12_symbolic [] =
	"# Lesson 12: Derivatives, integrals, limits\n"
	"[lessons]\n"
	"symbolic.title = Derivatives, integrals, limits\n"
	"symbolic.stage = 2\n"
	"\n"
	"symbolic.1.check = result\n"
	"symbolic.1.param = 3x\302\262\n"
	"symbolic.1.text = Names that stand for nothing are symbols inside the\n"
	"    symbolic functions. Differentiate x^3 with diff(x^3, x).\n"
	"symbolic.1.answer = diff(x^3, x)<Enter>\n"
	"\n"
	"symbolic.2.check = result\n"
	"symbolic.2.param = 9\n"
	"symbolic.2.text = Integrate x^2 from 0 to 3: integrate(x^2, x, 0, 3).\n"
	"symbolic.2.answer = integrate(x^2, x, 0, 3)<Enter>\n"
	"\n"
	"symbolic.3.check = result\n"
	"symbolic.3.param = 1\n"
	"symbolic.3.text = A limit: limit(sin(x)/x, x, 0).\n"
	"symbolic.3.answer = limit(sin(x)/x, x, 0)<Enter>\n";

static const char text_lessons_en_13_units [] =
	"# Lesson 13: Units\n"
	"[lessons]\n"
	"units.title = Units\n"
	"units.stage = 2\n"
	"\n"
	"units.1.check = result\n"
	"units.1.param = 5300 m\n"
	"units.1.text = Units are part of numbers: write 5 km + 300 m.\n"
	"units.1.answer = 5 km + 300 m<Enter>\n"
	"\n"
	"units.2.check = result\n"
	"units.2.param = 1143/1250 m\n"
	"units.2.text = to converts: write 3 ft to m.\n"
	"units.2.answer = 3 ft to m<Enter>\n";

static const char text_lessons_en_14_numsys [] =
	"# Lesson 14: Complex numbers, quaternions, statistics\n"
	"[lessons]\n"
	"numsys.title = Complex numbers, quaternions, statistics\n"
	"numsys.stage = 2\n"
	"\n"
	"numsys.1.check = result\n"
	"numsys.1.param = 5 + 5i\n"
	"numsys.1.text = i is the imaginary unit. Multiply (1+2i)*(3-i).\n"
	"numsys.1.answer = (1+2i)*(3-i)<Enter>\n"
	"\n"
	"numsys.2.check = result\n"
	"numsys.2.param = 2i\n"
	"numsys.2.text = The square root of a negative number is complex: sqrt("
	"-4).\n"
	"numsys.2.answer = sqrt(-4)<Enter>\n"
	"\n"
	"numsys.3.check = result\n"
	"numsys.3.param = k\n"
	"numsys.3.text = Quaternions use i, j and k: write i*j.\n"
	"numsys.3.answer = i*j<Enter>\n"
	"\n"
	"numsys.4.check = result\n"
	"numsys.4.param = 5/2\n"
	"numsys.4.text = Statistics: the mean of a list, mean([1,2,3,4]).\n"
	"numsys.4.answer = mean([1,2,3,4])<Enter>\n";

static const char text_lessons_en_15_domains2 [] =
	"# Lesson 15: Boolean algebra and lambda calculus\n"
	"[lessons]\n"
	"domains2.title = Boolean algebra and lambda calculus\n"
	"domains2.stage = 2\n"
	"\n"
	"domains2.1.check = result\n"
	"domains2.1.param = true\n"
	"domains2.1.text = Other domains have their own syntax. Switch with\n"
	"    {ACTION_COMMAND}, mode boolean, then start a block and write a | ~"
	"a.\n"
	"domains2.1.answer = <ACTION_COMMAND>mode boolean<Enter><ACTION_BLOCK_N"
	"EW>a | ~a<Enter>\n"
	"\n"
	"domains2.2.check = result\n"
	"domains2.2.param = y\n"
	"domains2.2.text = The lambda calculus: switch with mode lambda, start "
	"a\n"
	"    block and write (\316\273x. x) y. The result is the reduced term.\n"
	"domains2.2.answer = <ACTION_COMMAND>mode lambda<Enter><ACTION_BLOCK_NE"
	"W>(\316\273x. x) y<Enter>\n";

